import wiki from './place-wiki.json';
import siteWiki from './sites/site-wiki.json';

// What the place panel shows about a place, by its name on the map. Summaries and facts come from A Wiki of Ice and Fire
// (src/place-wiki.json, generated by tools/wiki/place-info.mjs); entries written here go on top of them.
export interface PlaceInfo {
  /** Photo or art at the top of the panel (URL or path under public/). */
  image?: string;
  /** The gallery: file names of the article's pictures, as in awoiaf's thumb.php?f=. */
  images?: string[];
  /** The wiki's caption for each picture in `images`, same order; '' where it has none. */
  captions?: string[];
  /** The text below may hold wiki links, [label](Page_title#section), which the panel turns into links to awoiaf. */
  summary?: string;
  /** Rows under the summary, [label, value]: ['Ruler', 'House Stark'], ['Founded', 'Age of Heroes']. */
  facts?: [string, string][];
  /** Houses tied to the place (seat, government, great house of a region): [article title, sigil file in public/sigils, full name]. */
  houses?: [string, string, string][];
  /** Title of the place's article on A Wiki of Ice and Fire, when the text is from there. */
  wiki?: string;
}

export const PLACE_INFO: Record<string, PlaceInfo> = { ...(wiki as unknown as Record<string, PlaceInfo>) };

// The named places of the 3D sites (Winterfell, King's Landing): each one's passage from its site's wiki article
// (src/sites/site-wiki.json, tools/sites/site-wiki.mjs), and the map's own entry for a road or water the site shares with it.
for (const [name, info] of Object.entries(siteWiki as unknown as Record<string, PlaceInfo>)) PLACE_INFO[name] ??= info;
const SHARED: Record<string, string> = { Kingsroad: 'The Kingsroad', Goldroad: 'The Gold Road', 'Blackwater Rush': 'The Blackwater Rush' };
for (const [name, key] of Object.entries(SHARED)) if (PLACE_INFO[key]) PLACE_INFO[name] ??= PLACE_INFO[key];

